import {FASHION_ITEMS,FASHION} from './fashion-catalogue.js';
import {FURNITURE_ITEMS,FURNITURE} from './furniture-catalogue.js';
import {buyFurniture} from './decor-state.js';
import {salonQuote,completeSalon} from './shops-state.js';
export const money=n=>'₦'+n.toLocaleString('en-NG');
export function createSalonService({root,state,save,speak,location,position,onComplete,onWorking=()=>{}}){
 let phase='greeting',quote=null,elapsed=0,disposed=false;
 const el=id=>root.querySelector('#'+id),say=text=>speak([{speaker:'Stylist',text}]);
 function render(){
 root.innerHTML='<h2>Hair Salon</h2><p id="salon-line" role="status"></p><div id="salon-actions"></div>';
 const actions=el('salon-actions');let line='Welcome. Which hairstyle would you like us to discuss?';
 if(phase==='greeting'){actions.innerHTML='<button id="salon-browse">I would like to see the styles</button>';el('salon-browse').onclick=()=>{phase='browse';render();};}
 if(phase==='browse'){line='Choose a style. I will explain the price before we start.';actions.innerHTML=FASHION_ITEMS.filter(i=>i.category==='Hair').map(i=>'<button id="style-'+i.id+'">'+i.name+' · '+money(salonQuote(state,i.id).price)+'</button>').join('');for(const i of FASHION_ITEMS.filter(i=>i.category==='Hair'))el('style-'+i.id).onclick=()=>{quote=salonQuote(state,i.id);phase='confirm';render();};}
 if(phase==='confirm'){line='You chose '+quote.name+'. '+FASHION[quote.id].detail+' The service costs '+money(quote.price)+'. '+(quote.price===0?'You already own this style. ':'')+'Shall I begin?';actions.innerHTML='<button id="salon-confirm">Yes, begin · '+money(quote.price)+'</button><button id="salon-cancel">No, keep my current hair</button>';el('salon-confirm').disabled=state.money<quote.price;el('salon-confirm').onclick=()=>{if(phase!=='confirm'||disposed)return;phase='working';elapsed=0;onWorking(true);render();};el('salon-cancel').onclick=()=>{phase='browse';render();say('No problem. Your hair and balance are unchanged.');};if(state.money<quote.price)line+=' You need '+money(quote.price-state.money)+' more; nothing has been charged.';}
 if(phase==='working'){line='I am styling your hair now. Hold still a moment.';actions.innerHTML='<progress id="salon-progress" max="5" value="0" aria-label="Styling progress"></progress><button id="salon-stop">Cancel service · no charge</button>';el('salon-stop').onclick=()=>{onWorking(false);phase='browse';render();say('Service cancelled. No charge; your original hairstyle is unchanged.');};}
 el('salon-line').textContent=line;say(line);
 }
 render();return {tick(dt){if(disposed||phase!=='working')return;elapsed+=dt;el('salon-progress').value=elapsed;if(elapsed<5)return;phase='done';onWorking(false);const r=completeSalon(state,quote,location(),position());if(r.ok){onComplete();save();}root.innerHTML='<h2>'+ (r.ok?'Style complete':'Service stopped')+'</h2><p id="salon-result" role="status"></p><button id="salon-again">Discuss another style</button>';el('salon-result').textContent=r.message;say(r.message);el('salon-again').onclick=()=>{phase='browse';render();};},dispose(){disposed=true;onWorking(false);}};
}
export function createFurnitureShop({root,state,save,speak=()=>{},guide,place,onSofa=()=>{},selected=null}){
 let item=FURNITURE[selected]||null,order=null,done=false,disposed=false;
 const el=id=>root.querySelector('#'+id);
 function show(){root.innerHTML='<h2>Furniture showroom</h2><p>Individual pieces · delivery to your home storage included. Place them when you get home.</p><div class="shop-grid">'+FURNITURE_ITEMS.map(i=>'<button id="furniture-'+i.id+'">'+i.name+'<small>'+i.detail+' · '+money(i.price)+'</small></button>').join('')+'</div><div id="furniture-selection"></div><button id="furniture-sofa">Installed home sofa · ₦3,000</button><button id="furniture-home">My home storage / placement</button><button id="furniture-visit">Visit the showroom</button>';for(const i of FURNITURE_ITEMS)el('furniture-'+i.id).onclick=()=>{item=i;order=globalThis.crypto.randomUUID();done=false;detail();};el('furniture-sofa').disabled=state.furniture;el('furniture-sofa').onclick=()=>{item=null;el('furniture-selection').innerHTML='<h3>Installed home sofa</h3><p>₦3,000, including delivery and installation in the existing living-room position. Keep the sofa area clear.</p><button id="sofa-confirm">Confirm sofa purchase · ₦3,000</button><button id="sofa-cancel">Cancel · no charge</button>';el('sofa-confirm').onclick=()=>{if(!disposed&&!state.furniture)onSofa();};el('sofa-cancel').onclick=()=>el('furniture-selection').innerHTML='';speak([{speaker:'Showroom attendant',text:'The home sofa is ₦3,000 including delivery and installation. Would you like to confirm?'}]);};el('furniture-home').onclick=place;el('furniture-visit').onclick=()=>guide('showroom');if(item){order=globalThis.crypto.randomUUID();detail();}}
 function detail(){el('furniture-selection').innerHTML='<h3>'+item.name+'</h3><p>'+item.detail+' · '+item.w+' × '+item.d+' m</p><p>Total '+money(item.price)+'. Deliver directly to my home storage?</p><button id="furniture-confirm">Confirm purchase and delivery</button><button id="furniture-cancel">Keep browsing</button><p id="furniture-result" role="status"></p>';speak([{speaker:'Showroom attendant',text:item.name+' costs '+money(item.price)+'. Delivery to your home storage is included. Shall we go ahead?'}]);el('furniture-confirm').disabled=state.money<item.price;el('furniture-cancel').onclick=()=>{item=null;el('furniture-selection').innerHTML='';speak([{speaker:'Showroom attendant',text:'No charge. Take your time with the other pieces.'}]);};const chosen=item.id,receipt=order;el('furniture-confirm').onclick=()=>{if(done||disposed||item?.id!==chosen||order!==receipt)return;const r=buyFurniture(state,chosen,receipt);if(r.ok){done=true;save();el('furniture-confirm').disabled=true;}const message=r.ok?'Delivered to your home storage. You own this piece; use My home storage / placement to position it.':r.message;el('furniture-result').textContent=message;speak([{speaker:'Showroom attendant',text:message}]);};}
 show();return {tick(){},dispose(){disposed=true;}};
}
